namespace Ota {
bool loadJson(const std::string &p,Json &j,size_t limit){std::string raw;return readFile(p,raw,limit)&&parse(raw,j,limit);}
bool loadConfig(Json &j){if(!loadJson("/user/pandanote/config/ota.json",j,65536)||!j.keys("schema,device_id,model,channel,keys,helper_path,helper_sha256")||j.num("schema")!=1||!identifier(j.text("device_id"))||!identifier(j.text("model"))||!identifier(j.text("channel"))||j.get("keys").type!=Json::Object||j.get("keys").object.empty()||j.get("keys").object.size()>8||!hex(j.text("helper_sha256")))return false;std::string prefix="/user/pandanote/apps/releases/",suffix="/ota/pandanote-ota-upgrade.mipsel",path=j.text("helper_path");return path.size()==prefix.size()+64+suffix.size()&&path.find(prefix)==0&&hex(path.substr(prefix.size(),64))&&path.substr(prefix.size()+64)==suffix;}
bool baseline(Json &j,std::string &raw){return readFile(std::string(stateRoot())+"/baseline.json",raw,256*1024)&&parse(raw,j,256*1024)&&j.num("schema")==1&&validateFiles(j.get("files"),j.text("native_sha256"),j.text("boot_id"),true);}
bool request(const Json &c,Json &r,std::string &error){Json b,ledger;std::string raw;error="baseline_mismatch";if(!baseline(b,raw)||!rootReadOnly()||!closure(b.get("files")))return false;std::string current,entry,ready;if(!hashFile("/user/pandanote/apps/current",current)||!hashFile("/etc/inittab",entry)||!readFile("/run/pandanote-normal/early.ready",ready,64)||ready!=b.text("boot_id")+"\n")return false;
 int fd=open("/dev/mmcblk0p2",O_RDONLY|O_NOFOLLOW|O_CLOEXEC);char block[1024];if(fd<0)return false;ssize_t n=pread(fd,block,sizeof block,1024);close(fd);if(n!=sizeof block)return false;
 r=Json::obj();r.object["schema"]=Json::integer(1);r.object["ota_abi"]=Json::integer(1);r.object["request_nonce"]=Json(randomHex(32));if(!hex(r.text("request_nonce")))return false;r.object["model"]=c.get("model");r.object["channel"]=c.get("channel");r.object["old_package_sha256"]=Json(digest(raw));r.object["old_native_sha256"]=b.get("native_sha256");r.object["old_boot_id"]=b.get("boot_id");r.object["old_current_sha256"]=Json(current);r.object["old_inittab_sha256"]=Json(entry);r.object["live_superblock_sha256"]=Json(digest(std::string(block,sizeof block)));
 if(!loadJson(std::string(stateRoot())+"/accepted.json",ledger,4096)||!ledger.keys("sequence,release_sha256")||ledger.num("sequence")<0||!hex(ledger.text("release_sha256"))){error="storage_insufficient";return false;}r.object["highest_sequence"]=ledger.get("sequence");error="none";return true;}
std::string attemptPath(const std::string &id){return hex(id,32)?std::string(stateRoot())+"/attempts/"+id:std::string();}
bool loadAttempt(const std::string &id,const Json &config,Authorization &a,Json &req,std::string &error,bool allowExpired){std::string dir=attemptPath(id);Json response,ledger;if(dir.empty()||!directory(dir)||!loadJson(dir+"/request.json",req,4096)||!loadJson(dir+"/offer.json",response)||!loadJson(std::string(stateRoot())+"/accepted.json",ledger,4096))return false;Json c=config;c.object["accepted_release_sha256"]=ledger.get("release_sha256");if(ledger.num("sequence")>req.num("highest_sequence"))req.object["highest_sequence"]=ledger.get("sequence");int64_t now=epoch();if(allowExpired){Json env;std::string raw;if(!envelope(response.get("deployment"),"PANDANOTE-OTA-DEPLOYMENT-1\n",c.get("keys"),16384,env,raw))return false;now=env.num("issued_at");}return authorize(response,c,req,now,a,error);}
bool noPowerRequest(){const char *names[]={"/run/pandanote-normal/poweroff.request","/run/pandanote-normal/suspend.request","/run/pandanote-normal/suspend.active","/run/pandanote-normal/suspend.entered"};for(unsigned i=0;i<4;i++){struct stat s;if(!lstat(names[i],&s)||errno!=ENOENT)return false;}return true;}
bool prepareValid(const std::string &id,const std::string &generation,Process *native){Json q,p;if(!loadJson(std::string(runRoot())+"/prepare.request",q,4096)||!loadJson(std::string(runRoot())+"/prepare.reply",p,4096)||p.text("attempt_id")!=id||p.text("generation")!=generation||q.text("attempt_id")!=id||q.text("generation")!=generation||p.text("result")!="ready"||p.num("schema")!=1||q.num("schema")!=1||bootMs()-p.num("heartbeat_ms")>3000||p.num("heartbeat_ms")>bootMs()||p.num("native_pid")!=q.num("native_pid")||p.num("native_starttime")!=q.num("native_starttime"))return false;Process actual;Json activity;if(!loadJson(std::string(runRoot())+"/activity.json",activity,4096)||activity.num("time_trusted")!=1||activity.num("awake")!=1||activity.num("shutdown")!=0||activity.num("native_pid")!=p.num("native_pid")||activity.num("native_starttime")!=p.num("native_starttime")||bootMs()-activity.num("heartbeat_ms")>3000||activity.num("heartbeat_ms")>bootMs())return false;if(!process(p.num("native_pid"),actual)||actual.start!=p.num("native_starttime"))return false;if(native)*native=actual;return true;}
}
// 独立 OTA 入口；既有 NORMAL/RAM 调用契约保持独立。
struct GateContext {std::string id,generation;Ota::Process worker,supervisor;int64_t expires;GateContext():expires(0){}};
static GateContext &gate(){static GateContext c;return c;}
extern "C" int pandanote_ota_gate(int *argc,char ***argv){using namespace Ota;if(*argc!=3||std::string((*argv)[1])!="--apply"||geteuid()!=0)return -1;gate().id=(*argv)[2];Json c,r,state;Authorization a;std::string error,helper;std::string dir=attemptPath(gate().id);if(dir.empty()||!loadConfig(c)||!loadAttempt(gate().id,c,a,r,error)||!loadJson(std::string(stateRoot())+"/state.json",state,65536)||state.text("state")!="APPLYING"||state.text("attempt_id")!=gate().id||state.num("confirmed")!=1||!hashFile("/proc/self/exe",helper,0,true)||helper!=a.deployment.text("helper_sha256")||!validateBundle(dir+"/bundle",a)||!rootReadOnly())return -1;Ota::Process self,service,native,app;std::string pid;
 if(!process(getpid(),self)||!process(self.ppid,gate().worker)||!process(gate().worker.ppid,gate().supervisor)||!process(gate().supervisor.ppid,service)||!readFile("/run/pandanote-normal/ota.pid",pid,32)||pid!=decimal(gate().supervisor.pid)+"\n"||gate().supervisor.exe!="/bin/busybox"||gate().supervisor.sid!=gate().supervisor.pid||gate().supervisor.pgid!=gate().supervisor.pid||gate().worker.sid!=gate().supervisor.pid||gate().worker.pgid!=gate().supervisor.pid||self.sid!=gate().supervisor.pid||self.pgid!=gate().supervisor.pid||service.ppid!=1||gate().worker.exe!="/user/pandanote/apps/releases/"+a.deployment.text("old_native_sha256")+"/ota/ota-worker.mipsel"||!prepareValid(gate().id,state.text("generation"),&native)||!process(native.ppid,app)||app.ppid!=service.pid||app.pid==gate().supervisor.pid)return -1;
 gate().generation=state.text("generation");gate().expires=a.deployment.num("expires_at");if(pandanote_ota_final_check())return -1;std::string proof;if(!readFile(dir+"/proof",proof,4096))return -1;static std::string args[5];static char*av[6];args[0]="pandanote-ota-upgrade";args[1]=dir+"/bundle";args[2]=a.deployment.text("bundle_sha256");args[3]=dir+"/proof";args[4]=digest(proof);for(unsigned i=0;i<5;i++)av[i]=const_cast<char*>(args[i].c_str());av[5]=0;*argc=5;*argv=av;return 0;}
extern "C" int pandanote_ota_final_check(void){using namespace Ota;Process worker,supervisor;if(getppid()!=gate().worker.pid||!process(gate().worker.pid,worker)||!sameProcess(worker,gate().worker)||!process(gate().supervisor.pid,supervisor)||!sameProcess(supervisor,gate().supervisor))return -1;return epoch()>=gate().expires||!safePower()||!noPowerRequest()||!prepareValid(gate().id,gate().generation)?-1:0;}
